<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\User; use App\Services\AdminAudit; use Illuminate\Http\Request; use Illuminate\Support\Facades\Password;
class UserController extends Controller { public function index(Request $r){$q=User::query()->withCount('ownedRestaurants');if($r->filled('q'))$q->where(fn($x)=>$x->where('name','like','%'.$r->q.'%')->orWhere('email','like','%'.$r->q.'%'));if($r->filled('role'))$q->where('role',$r->role);return view('admin.users.index',['users'=>$q->latest()->paginate(30)->withQueryString()]);} public function update(Request $r,User $user,AdminAudit $audit){abort_if($user->id===$r->user()->id&&($r->input('status')!=='active'||$r->input('role')!=='admin'),422,'Vous ne pouvez pas vous retirer vos propres accès.');$d=$r->validate(['role'=>'required|in:user,restaurant_owner,admin','status'=>'required|in:active,disabled','must_change_password'=>'nullable|boolean']);$d['must_change_password']=$r->boolean('must_change_password');$user->update($d);$audit->record('user.updated',$user,$d);return back()->with('status','Utilisateur enregistré.');} public function reset(User $user,AdminAudit $audit){Password::sendResetLink(['email'=>$user->email]);$audit->record('user.password_reset_sent',$user);return back()->with('status','Lien de réinitialisation envoyé.');}}
